//! Run rez's bundled benchmark dataset through rer and report solve timing,
//! comparing against rez's own recorded solve times.
//!
//! Requires the fixtures generated by `scripts/prepare_benchmark_data.py`
//! (from the `rez` git submodule). Run with:
//!
//! ```text
//! cargo run --release -p examples --example rez_benchmark_dataset
//! ```

use rer_resolver::{solver_with_packages, LocalPackages, PackageData};
use serde::Deserialize;
use std::collections::HashMap;
use std::path::PathBuf;
use std::time::Instant;

type PackageRepo = HashMap<String, HashMap<String, PackageData>>;

#[derive(Deserialize)]
struct BenchmarkCase {
    request: Vec<String>,
    /// rez's recorded wall-clock solve time, in seconds.
    resolve_time: Option<f64>,
}

fn data_set_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../data_set")
}

fn load_json<T: for<'de> Deserialize<'de>>(name: &str) -> T {
    let path = data_set_dir().join(name);
    let data = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "failed to read {} ({e}) — generate fixtures with:\n  \
             python scripts/prepare_benchmark_data.py",
            path.display()
        )
    });
    serde_json::from_str(&data)
        .unwrap_or_else(|e| panic!("failed to parse {}: {e}", path.display()))
}

/// Nearest-rank percentile of an already-sorted slice.
fn percentile(sorted: &[f64], p: f64) -> f64 {
    if sorted.is_empty() {
        return 0.0;
    }
    let idx = ((p / 100.0) * (sorted.len() - 1) as f64).round() as usize;
    sorted[idx]
}

fn main() {
    let repo: PackageRepo = load_json("benchmark_packages.json");
    let cases: Vec<BenchmarkCase> = load_json("benchmark_expected.json");

    println!(
        "running {} requests against {} package families\n",
        cases.len(),
        repo.len()
    );

    let mut times_ms: Vec<f64> = Vec::with_capacity(cases.len());
    let mut solved = 0usize;
    let mut failed = 0usize;
    let mut panicked = 0usize;

    // The solver can still panic on some inputs; catch those so the timing
    // report covers every request that the solver can actually process.
    let prev_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(|_| {}));

    for case in &cases {
        let request: Vec<&str> = case.request.iter().map(|s| s.as_str()).collect();
        // Build the repo outside the timer so we measure only solve time.
        let mut packages = LocalPackages::from_packages(repo.clone());
        let start = Instant::now();
        let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            solver_with_packages(request, &mut packages)
        }));
        let elapsed_ms = start.elapsed().as_secs_f64() * 1000.0;
        match outcome {
            Ok(Ok(_)) => {
                solved += 1;
                times_ms.push(elapsed_ms);
            }
            Ok(Err(_)) => {
                failed += 1;
                times_ms.push(elapsed_ms);
            }
            // Panic time is meaningless — exclude it from the stats.
            Err(_) => panicked += 1,
        }
    }

    std::panic::set_hook(prev_hook);

    if times_ms.is_empty() {
        println!("rer: 0 solved, 0 failed, {panicked} panicked — no timing to report");
        return;
    }

    let total: f64 = times_ms.iter().sum();
    let mean = total / times_ms.len() as f64;
    let mut sorted = times_ms.clone();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());

    println!("rer: {solved} solved, {failed} failed, {panicked} panicked");
    println!("  total  {total:>10.1} ms");
    println!("  mean   {mean:>10.2} ms");
    println!("  median {:>10.2} ms", percentile(&sorted, 50.0));
    println!("  p95    {:>10.2} ms", percentile(&sorted, 95.0));
    println!(
        "  min    {:>10.2} ms",
        sorted.first().copied().unwrap_or(0.0)
    );
    println!(
        "  max    {:>10.2} ms",
        sorted.last().copied().unwrap_or(0.0)
    );

    let rez_total: f64 = cases.iter().filter_map(|c| c.resolve_time).sum::<f64>() * 1000.0;
    if rez_total > 0.0 {
        println!(
            "\nrez (recorded, all {} requests): total {rez_total:.1} ms",
            cases.len()
        );
        if panicked == 0 && failed == 0 {
            // Only a like-for-like comparison when rer processed every request.
            println!("rer is {:.2}x rez", rez_total / total);
        } else {
            println!(
                "(not directly comparable — rer timing covers {} of {} requests)",
                times_ms.len(),
                cases.len()
            );
        }
    }
}
